        _ = &offset;
        while ((offset < bytes.len)) {
            switch (bun.sys.pwrite(fd, bytes[offset..], written)) {
.err => |e| {
if ((e.getErrno() == .AGAIN)) {
                continue;
            }
            _ = bun.Output.debugWarn("Failed to write to memfd: {f}", .{ e });
            _ = fd.close();
            return .{ .err = e };
},
.result => |result| {
if ((result == 0)) {
                _ = bun.Output.debugWarn("Failed to write to memfd: EOF", &.{});
                _ = fd.close();
                return .{ .err = bun.sys.Error.fromCode(.NOMEM, .write) };
            }
            written = (written + (if (comptime @typeInfo(@TypeOf(result)) == .@"enum") cp_cast_int(isize, @intFromEnum(result)) else cp_cast_int(isize, result)));
            offset = (offset + result);
},
}
        }
        var linux_memfd_allocator = LinuxMemFdAllocator.new(.{ .fd = fd, .ref_count = RefCount.init(), .size = bytes.len });
        _ = &linux_memfd_allocator;
        switch (linux_memfd_allocator.alloc(bytes.len, 0, .{ .TYPE = .SHARED })) {
.result => |res| {
return .{ .result = res };
},
.err => |e| {
_ = linux_memfd_allocator.deref();
        return .{ .err = e };
},
}
}

pub fn isInstance(allocator_: Allocator) bool {
        return (allocator_.vtable == allocator_vtable);
}
pub const new = bun.TrivialNew(@This());
pub const ref = RefCount.ref;
pub const deref = RefCount.deref;
const Allocator = std.mem.Allocator;
const VTableType = Allocator.VTable;
const Bytes = bun.webcore.Blob.Store.Bytes;
const RefCount = bun.ptr.ThreadSafeRefCount(LinuxMemFdAllocator, "ref_count", LinuxMemFdAllocator.deinit, .{});
var memfd_counter = std.atomic.Value(usize).init(0);
const allocator_vtable_val = VTableType{ .alloc = (&AllocatorInterface.alloc), .resize = (&Allocator.noResize), .remap = (&Allocator.noRemap), .free = (&AllocatorInterface.free) };
const allocator_vtable = (&allocator_vtable_val);
